// DecodeInstanceObjectSrc unmarshals a stored resource instance object.
func DecodeInstanceObjectSrc(os *ResourceInstanceObjectSrc, ty cty.Type) (*ResourceInstanceObject, error) {
	if os == nil {
		return nil, nil
